    palette: darkPalette,
    typography: typography,
    shape: shape,

    components: {
        ...darkCardTheme,
        ...darkButtonTheme,
        ...darkAppBarTheme,
        ...darkTypographyTheme,
        ...darkBadgeTheme,

        MuiCssBaseline: {
            styleOverrides: {
                body: {
                    margin: 0,
                    padding: 0,
                    minHeight: '100vh',
                    transition: 'background 0.3s ease',
                    // Используем относительный путь от корня сайта
                    background: `url('/img/background/background_dark.png') no-repeat center center fixed`,
                    backgroundSize: 'cover',
                },
            },
        },

        MuiPaper: {
            styleOverrides: {
                root: {
                    borderRadius: shape.borderRadius,
                    backgroundColor: 'rgba(30, 30, 30, 0.9)',
                    backdropFilter: 'blur(10px)',
                    transition: 'background-color 0.3s ease, box-shadow 0.3s ease',
                },
            },
        },
    },
};

// Создаем готовые темы с помощью createTheme
export const lightTheme = createTheme(lightThemeOptions);
export const darkTheme = createTheme(darkThemeOptions);

// Экспортируем также отдельные части для возможного использования в компонентах
export { lightPalette, darkPalette, typography, shape };
